{
  "IP": "neorv32_hwspinlock",
  "Conceptual Assets": [
    {
      "Concept ID": "C1",
      "Concept Name": "Hardware lock state",
      "Unit": "neorv32_hwspinlock",
      "Information": "The 32-bit state of the hardware spinlocks, which the IP stores, updates and reports so bus masters can coordinate access to shared resources.",
      "Rubric": {
        "Confidentiality": "no",
        "Integrity": "yes",
        "Availability": "yes",
        "Undermined Expected Behavior": "no"
      },
      "Rubric Reason": "The lock vector is security-sensitive synchronization state, and a bus request can change a selected bit through line 45 while reset can clear it at line 42. Keeping a lock bit asserted can prevent another requester from acquiring the shared resource, and the update path at line 45 can therefore cause lock acquisition to be blocked.",
      "Objectives At Risk": [
        "I",
        "A"
      ],
      "Attack": "An attacker can issue requests that alter selected lock bits, keeping a resource locked or clearing another owner's lock and thereby corrupting ownership or denying lock acquisition.",
      "Enters Through": [
        "bus_req_i.rw"
      ],
      "Leaves Through": [
        "bus_rsp_o.data"
      ],
      "Entry Lines": [
        45
      ],
      "Held Lines": [
        42,
        45
      ],
      "Exit Lines": [
        68,
        70
      ]
    },
    {
      "Concept ID": "C2",
      "Concept Name": "Per-lock access selection",
      "Unit": "neorv32_hwspinlock",
      "Information": "The internal selection decision derived from the request address that chooses which lock bit an access updates and which lock status is returned. It has no entry or exit port because the address computes an internal selection decision rather than carrying that decision across the boundary.",
      "Rubric": {
        "Confidentiality": "no",
        "Integrity": "yes",
        "Availability": "yes",
        "Undermined Expected Behavior": "no"
      },
      "Rubric Reason": "The selector is security-relevant control information because it determines which lock an access affects; line 51 derives it from bus_req_i.addr and line 44 uses it to gate the corresponding lock update. Steering the selector away from the intended lock can withhold that lock's update and return the wrong lock status, as shown by lines 44 and 68.",
      "Objectives At Risk": [
        "I",
        "A"
      ],
      "Attack": "An attacker can present an address that selects a different lock, causing an acquisition or release to affect the wrong resource and leaving the intended lock unavailable.",
      "Enters Through": [],
      "Leaves Through": [],
      "Entry Lines": [],
      "Held Lines": [
        51
      ],
      "Exit Lines": []
    }
  ],
  "Not Kept": [
