      "Candidate Unit": "neorv32_hwspinlock",
      "Merged Into": "C1",
      "Why Not Kept": ""
    },
    {
      "Candidate Name": "Lock status read-back",
      "Candidate Unit": "neorv32_hwspinlock",
      "Merged Into": "C1",
      "Why Not Kept": ""
