    {
      "Candidate Name": "Clock and reset",
      "Candidate Unit": "neorv32_hwspinlock",
      "Merged Into": "",
      "Why Not Kept": "The clock and reset exclusion bars them as conceptual assets even though they time or initialize lock_q and bus_rsp_o."
    },
    {
      "Candidate Name": "Bus response acknowledge and error",
      "Candidate Unit": "neorv32_hwspinlock",
      "Merged Into": "",
      "Why Not Kept": "The acknowledge only copies the request strobe and the error is tied to a constant, so they carry no independent security-relevant information."
    },
    {
      "Candidate Name": "Bus access command fields",
      "Candidate Unit": "neorv32_hwspinlock",
      "Merged Into": "",
      "Why Not Kept": "The strobe, direction and register-selection fields are access-command information rather than independent assets; the direction contributes to C1 and the per-lock decode is represented by C2."
    }
  ],
